def _main_transcript_path(run_path):
    """The session-level transcript a worker run belongs to: `<project-dir>/<session-id>.jsonl`, the
    sibling file the harness writes beside the `<session-id>/subagents/` directory a worker run sits
    under. `run_path` names one `agent-*.jsonl` worker-run file; walking up two directories reaches
    the session directory, and its basename names the session whose sibling file this is.
    """
    session_dir = os.path.dirname(os.path.dirname(run_path))
    session_id = os.path.basename(session_dir)
    project_dir = os.path.dirname(session_dir)
    return os.path.join(project_dir, session_id + ".jsonl")


def _session_started_at(run_path, cache=None):
    """The timestamp of the first stamped record in the session's own main transcript -- the
    harness's own record of when this session began, not a guess read off a file's mtime.

    A session's main transcript is written append-only as the session runs, so its first stamped
    record is also its earliest: reading top to bottom and stopping at the first `timestamp` a
    record carries is enough, and it matches the file's own creation time (checked by hand against
    this delivery's own session, ROADMAP row 780's correction).

    None when the file is missing, unreadable, or carries no stamped record at all -- the gate
    cannot place the session's start in time, and is_unarmed_session reads that the same
    conservative way every other unplaceable reading in this file already does: it does not exempt
    the finding. Read once per session and cached, since several worker runs can share one session.
    """
    main = _main_transcript_path(run_path)
    if cache is not None and main in cache:
        return cache[main]
    started = None
    try:
        fh = open(main, encoding="utf-8", errors="replace")
    except OSError:
        fh = None
    if fh is not None:
        with fh:
            for line in fh:
                line = line.strip()
                if not line.startswith("{"):
                    continue
                try:
                    rec = json.loads(line)
                except ValueError:
                    continue
                ts = rec.get("timestamp")
                if isinstance(ts, str) and ts:
                    started = ts
                    break
    if cache is not None:
        cache[main] = started
    return started

